'use client';

import { useEffect, useState } from 'react';
import './rotating-headline.css';

export interface RotatingHeadlineProps {
  /** Text that stays put, shown before the rotating phrase. */
  prefix: string;
  /** Keep this array stable (define it outside the component). */
  phrases: string[];
  /** Time each phrase stays on screen, in milliseconds. */
  interval?: number;
  className?: string;
}

/** Swaps through a set of phrases. With reduced motion the swap is instant. */
export function RotatingHeadline({
  prefix,
  phrases,
  interval = 2200,
  className = '',
}: RotatingHeadlineProps) {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const timer = window.setInterval(
      () => setIndex((current) => (current + 1) % phrases.length),
      interval
    );
    return () => window.clearInterval(timer);
  }, [phrases, interval]);

  return (
    <p className={`mg-rotate ${className}`}>
      <span className='mg-rotate__sr'>
        {prefix} {phrases.join(', ')}
      </span>
      <span aria-hidden='true'>
        {prefix}{' '}
        <span className='mg-rotate__window'>
          <span key={index} className='mg-rotate__phrase'>
            {phrases[index]}
          </span>
        </span>
      </span>
    </p>
  );
}

.mg-rotate {
  margin: 0;
  font-weight: 700;
}

.mg-rotate__window {
  display: inline-block;
  overflow: hidden;
  vertical-align: bottom;
}

.mg-rotate__phrase {
  display: inline-block;
  color: var(--mg-accent-text, #dce9f7);
  animation: mg-rotate-in 480ms cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

.mg-rotate__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@keyframes mg-rotate-in {
  from {
    opacity: 0;
    transform: translateY(100%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-rotate__phrase {
    animation: none;
  }
}
